"""Reproduce the interactive correlation explorer from the frozen association table."""
from pathlib import Path
import json
import pandas as pd
from algorithmic_morphology.classification_data import HUMAN_LABELS,CLASS_LABELS
import argparse
p=argparse.ArgumentParser(description="Build the self-contained morphology association explorer.");p.add_argument('--report-dir',type=Path,default=Path('reports/full_catalog_20261020'));args=p.parse_args()
r=args.report_dir/'paper_v3_data';a=pd.read_csv(r/'associations.csv');a=a.where(a.notna(),None).astype(object).where(a.notna(),None)
labels={'C':'Concentration','A_raw':'Raw asymmetry','A_corrected':'Sky-corrected asymmetry',
'S_lotz2004_statmorph_like_v1_raw':'Lotz-like clumpiness · raw','S_lotz2004_statmorph_like_v1_corrected':'Lotz-like clumpiness · corrected',
'S_conselice2003_like_v1_raw':'Conselice-like clumpiness · raw','S_conselice2003_like_v1_corrected':'Conselice-like clumpiness · corrected',
'Gini_aperture_v1':'Aperture Gini','M20_aperture_v1':'Brightest-20% moment M₂₀','axis_ratio_positive_aperture_v1':'Positive-flux axis ratio'}
targets={**HUMAN_LABELS,**{f'class_{i}':'DECaLS10: '+s for i,s in enumerate(CLASS_LABELS)}}
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{margin:0;font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,#222)}h2{font-size:21px;margin:0 0 6px}p{margin:6px 0 14px}.muted{color:var(--muted-foreground,#666)}.controls{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.controls label{display:flex;flex-direction:column;gap:4px;font-size:12px}select{max-width:100%;padding:7px;font:inherit;background:var(--card,#fff);color:inherit;border:1px solid var(--border,#aaa);border-radius:6px}.scroll{overflow:auto}.row{display:grid;grid-template-columns:minmax(200px,1.3fr) minmax(170px,1fr) 60px;align-items:center;gap:10px;padding:7px 0;border-bottom:1px solid var(--border,#ddd);min-width:460px}.track{height:18px;background:var(--secondary,#eee);position:relative}.track:before{content:'';position:absolute;left:50%;height:100%;border-left:1px solid var(--foreground,#444);opacity:.3}.bar{height:100%;position:absolute}.score{text-align:right;font-variant-numeric:tabular-nums}.axis{display:flex;justify-content:space-between;font-size:11px}.count{font-size:11px;color:var(--muted-foreground,#666)}a{color:inherit;text-decoration:underline}.note{padding:14px;background:var(--card,#f5f5f5);border-radius:var(--radius,8px);margin-top:16px}
</style></head><body><h2>Morphology and classification: explore the associations</h2><p class="muted">84,200 morphology IDs · 32,288 galaxies with ≥2 human votes · 84,104 valid DECaLS10 vectors<br>Full report: 25 classification figures and 63 band panels on 21 saved embedding spaces.</p>
<div class="controls"><label>Class / human answer<select id="target"></select></label><label>Band<select id="band"><option>g</option><option selected>r</option><option>i</option></select></label><label>Comparison<select id="cohort"><option value="available">All available finite pairs</option><option value="human_zoobot_matched">Matched human + DECaLS10</option><option value="three_plus_human_votes">At least 3 human morphology votes</option><option value="galfit_adjusted">Adjusted for GALFIT brightness, radius, shape</option></select></label></div>
<p id="heading"></p><div class="scroll"><div class="row"><span>Morphology feature</span><span class="axis"><span>−1</span><span>0</span><span>+1</span></span><span class="score">ρ</span></div><div id="rows"></div></div>
<p class="muted" id="caption"></p><div class="note">Human values are raw answer fractions, distinct from the published consensus selections. Machine values are supplied <a href="https://huggingface.co/mwalmsley/zoobot-finetuned-decals10">DECaLS10</a> model probabilities. Correlations are descriptive; they do not measure accuracy or establish physical classes. Both asymmetry outputs and both clumpiness profiles remain.</div>
<script>const DATA=__DATA__,LABELS=__LABELS__,TARGETS=__TARGETS__;
const target=document.getElementById('target'),band=document.getElementById('band'),cohort=document.getElementById('cohort');for(const [key,label] of Object.entries(TARGETS)){const o=document.createElement('option');o.value=key;o.textContent=label;target.append(o)}target.value='p_visible_nucleus';
function draw(){const selected=DATA.filter(x=>x.band===band.value&&x.target===target.value&&x.cohort===cohort.value);const adjusted=cohort.value==='galfit_adjusted';document.getElementById('rows').innerHTML='';for(const d of selected){const v=adjusted?d.partial_rank:d.spearman;const row=document.createElement('div');row.className='row';const name=document.createElement('span');name.textContent=LABELS[d.metric];const count=document.createElement('div');count.className='count';count.textContent='finite pairs: '+d.n.toLocaleString();name.append(count);const track=document.createElement('span');track.className='track';const bar=document.createElement('span');bar.className='bar';bar.style.left=(v>=0?50:50+50*v)+'%';bar.style.width=(v===null?0:50*Math.abs(v))+'%';bar.style.background=v>=0?'var(--chart-1,#207b70)':'var(--chart-2,#b45137)';track.append(bar);const score=document.createElement('span');score.className='score';score.textContent=v===null?'—':v.toFixed(3);row.append(name,track,score);document.getElementById('rows').append(row)}document.getElementById('heading').textContent=TARGETS[target.value]+' · '+band.value+' band';document.getElementById('caption').textContent=adjusted?'Correlation of rank residuals after linear adjustment for fitted mean effective surface brightness, effective radius and axis ratio. This removes only the fitted rank-linear component.':'Spearman rank correlation ρ, using every eligible finite pair. Values and negative corrected indices are retained.'}
[target,band,cohort].forEach(el=>el.addEventListener('change',draw));draw();console.log('Association explorer loaded: '+DATA.length+' records; '+Object.keys(LABELS).length+' morphology features.');</script></body></html>'''
html=html.replace('__DATA__',json.dumps(a.to_dict('records'),allow_nan=False)).replace('__LABELS__',json.dumps(labels)).replace('__TARGETS__',json.dumps(targets))
(args.report_dir/'association_explorer.html').write_text(html)
